CREATE DATABASE IF NOT EXISTS skyfleet CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE skyfleet;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','pilot') NOT NULL DEFAULT 'pilot',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS drones(id INT AUTO_INCREMENT PRIMARY KEY,serial_no VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,model VARCHAR(100),status ENUM('idle','active','maintenance','offline') DEFAULT 'idle',api_key_hash CHAR(64) NOT NULL,last_seen_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assignments(id INT AUTO_INCREMENT PRIMARY KEY,drone_id INT NOT NULL,pilot_id INT NOT NULL,assigned_at DATETIME DEFAULT CURRENT_TIMESTAMP,unassigned_at DATETIME NULL,FOREIGN KEY(drone_id) REFERENCES drones(id) ON DELETE CASCADE,FOREIGN KEY(pilot_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_pilot_active(pilot_id,unassigned_at));
CREATE TABLE IF NOT EXISTS telemetry(id BIGINT AUTO_INCREMENT PRIMARY KEY,drone_id INT NOT NULL,battery_pct TINYINT UNSIGNED NOT NULL,latitude DECIMAL(9,6) NOT NULL,longitude DECIMAL(9,6) NOT NULL,altitude_m DECIMAL(7,2) NOT NULL,speed_ms DECIMAL(6,2) NOT NULL DEFAULT 0,recorded_at DATETIME NOT NULL,FOREIGN KEY(drone_id) REFERENCES drones(id) ON DELETE CASCADE,INDEX idx_drone_time(drone_id,recorded_at));
CREATE TABLE IF NOT EXISTS geofences(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,center_lat DECIMAL(9,6) NOT NULL,center_lng DECIMAL(9,6) NOT NULL,radius_m INT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS alerts(id INT AUTO_INCREMENT PRIMARY KEY,drone_id INT NOT NULL,type ENUM('low_battery','geofence_breach','offline') NOT NULL,message VARCHAR(255) NOT NULL,status ENUM('open','acknowledged','resolved') DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(drone_id) REFERENCES drones(id) ON DELETE CASCADE,INDEX idx_status(status,created_at));
